const POKEDEX_SPECIES = [];
const POKEDEX_META = {};

POKEDEX_ROWS.forEach(([dex, key, name, type1, type2, shape, gen, price, legendary, mythical], index) => {
  const base = PDX_TYPES[type1];
  const second = type2 ? PDX_TYPES[type2] : null;
  const primary = second ? mix(base.primary, second.primary, 0.22 + (dex % 5) * 0.03) : base.primary;
  const light = second ? mix(base.light, second.light, 0.18) : base.light;
  const deep = second ? mix(base.deep, second.deep, 0.16) : base.deep;
  const accent = (legendary || mythical) ? '#ffd166' : (second ? mix(base.accent, second.accent, 0.42) : PDX_ACCENTS[(dex * 5) % PDX_ACCENTS.length]);
  const typeLabel = `${base.name}${second ? ` / ${second.name}` : ''}`;
  const region = `${PDX_REGIONS[gen]} #${String(dex).padStart(3, '0')}`;
  ELEMENTS[key] = {
    name,
    primary,
    light,
    deep,
    accent,
    trait: `${typeLabel} · ${region} — ${PDX_TRAITS[type1][dex % 2]}`,
    blurb: `A ${typeLabel.toLowerCase()} pocket sprite from ${PDX_REGIONS[gen]}. ${PDX_BLURBS[type1][dex % 2]}`,
    greeting: PDX_GREETINGS[type1][dex % 2],
    likes: PDX_LIKES[type1],
  };
  const [geneName, icon, desc, effect] = PDX_GENES[type1];
  GENE_POWERS[key] = { name: geneName, icon, desc, effect };
  TITAN_NAMES[key] = `${name} Titan`;
  TYPE_EGG_BASE_PRICE[key] = price;
  TYPE_EGG_PRICE[key] = discountedEggPrice(price);
  POKEDEX_SPECIES.push(key);
  POKEDEX_META[key] = { dex, name, type1, type2, types: second ? [type1, type2] : [type1], shape, gen, legendary: !!legendary, mythical: !!mythical, region };
  const homes = new Set([...PDX_HOMES[type1], ...(second ? PDX_HOMES[type2].slice(0, 1) : [])]);
  homes.forEach((scene) => {
    if (SCENES[scene] && !SCENES[scene].species.includes(key)) SCENES[scene].species.push(key);
  });
  const partner = POKEDEX_ROWS[(index + 1) % POKEDEX_ROWS.length];
  HYBRID_NAMES[pairKey(key, partner[1])] = `${name} Bond`;
});

ELEMENT_KEYS.push(...POKEDEX_SPECIES);
